package com.jobpilot.application;import jakarta.validation.constraints.*;import java.time.*;public final class ApplicationDtos{private ApplicationDtos(){}public record CreateApplication(@NotNull Long jobId,String notes){}public record UpdateApplication(@NotNull ApplicationStatus status,String notes){}public record View(Long id,Long jobId,String title,String company,ApplicationStatus status,String notes,LocalDate appliedAt,LocalDateTime updatedAt){}public static View view(JobApplication a){return new View(a.getId(),a.getJob().getId(),a.getJob().getTitle(),a.getJob().getCompany(),a.getStatus(),a.getNotes(),a.getAppliedAt(),a.getUpdatedAt());}}
